/// <summary>
/// The <c>AVACreateContactPersonBasedOnGABController</c> class is the controller class for <c>Creating contact persons based on GAB</c>
/// </summary>
class AVACreateContactPersonBasedOnGABController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
///     AVA <c>new</c> method.
/// </summary>
protected void new()
{
    super();

    this.parmClassName(classStr(AVACreateContactPersonBasedOnGABService));
    this.parmMethodName(methodStr(AVACreateContactPersonBasedOnGABService, runService));
}

/// <summary>
///     AVA <c>newFromArgs</c> method.
/// </summary>
/// <param name="_args">
///     <c>Args</c> as type
/// </param>
/// <returns>
///     <c>AVACreateContactPersonBasedOnGABController</c> as return value
/// </returns>
public static AVACreateContactPersonBasedOnGABController newFromArgs(Args _args)
{
    AVACreateContactPersonBasedOnGABController controller;

    controller = new AVACreateContactPersonBasedOnGABController();
    controller.parmArgs(_args);
    // remove for activating value initialization of AVACreateContactPersonBasedOnGABContract.initialize()
    controller.parmLoadFromSysLastValue(false);

    return controller;
}

/// <summary>
///     AVA <c>main</c> method.
/// </summary>
/// <param name="_args">
///     <c>Args</c> as type
/// </param>
public static void main(Args _args)
{
    AVACreateContactPersonBasedOnGABController  controller;
    AVACreateContactPersonBasedOnGABContract    dataContract;
    SysOperationStartResult                     sysOperationStartResult;

    Common          locCommon;
    smmBusRelTable  locsmmBusRelTable;
    DirPartyTable   locDirPartyTable;
    Args            locArgs;

    #define.RelationTypeContactPerson('ContactPerson') 

    if (!_args)
    {
        throw error("@SYS25407");
    }

    controller  = AVACreateContactPersonBasedOnGABController::newFromArgs(_args);
    controller.parmExecutionMode(SysOperationExecutionMode::Synchronous);

    dataContract    = controller.getDataContractObject();

    if (_args)
    {
        if(     (   _args.menuItemType()    == MenuItemType::Action 
                &&  _args.menuItemName()    == menuItemActionStr(AVACreateContactPersonBasedOnGABBusRel))
            ||  (   _args.menuItemType()    == MenuItemType::Action
                &&  _args.menuItemName()    == menuItemActionStr(AVACreateContactPersonBasedOnGABBusRelDialog)  )
            ||  (   _args.menuItemType()    == MenuItemType::Display
                &&  _args.menuItemName()    == menuItemDisplayStr(smmContactsListPage)  )                           )
        {
            if (_args.record())
            {
                locCommon = _args.record();
                if(locCommon.TableId == tableNum(smmBusRelTable))
                {
                    locsmmBusRelTable = locCommon;
                    dataContract.parmBusRelAccount(locsmmBusRelTable.BusRelAccount);
                    dataContract.parmBusRelTypeId(locsmmBusRelTable.BusRelTypeId);
                }
                locDirPartyTable = DirPartyTable::findRec(locsmmBusRelTable.Party);
            }
            if(_args.menuItemName() == menuItemActionStr(AVACreateContactPersonBasedOnGABBusRel))
            {
                controller.parmShowDialog(false);
            }
            dataContract.parmDirPartyRoleType(DirPartyRoleType::BusRel);
        }
        //locArgs = new Args();
        locArgs = _args;
        dataContract.parmArgs(locArgs);
        dataContract.parmDirPartyRecId(locDirPartyTable.RecId);
        dataContract.parmDirPartyType(locDirPartyTable.type());
    }

    sysOperationStartResult = controller.startOperation();

    if(sysOperationStartResult == SysOperationStartResult::Started)
    {
        if(_args.menuItemName() != menuItemActionStr(AVACreateContactPersonBasedOnGABBusRel))   //suppress Service start message for adhoc generation
        {
            info("@NDX:NXAOperationStarted");
        }
    }
}
